contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address contract_address,
        address[] memory tos,
        uint[] memory vs
    ) public {
        // Precondition: only include non-empty calls here, so a successful call must have run the loop.
        require(tos.length > 0);
        require(vs.length > 0);
        require(tos.length == vs.length);
        require(contract_address != address(0));
        require(contract_address != address(c));

        uint256 beforeBalance = address(this).balance;

        bool reverted;
        bool returned;
        try c.transfer(contract_address, tos, vs) returns (bool r) {
            reverted = false;
            returned = r;
        } catch {
            reverted = true;
            returned = false;
        }

        assert(reverted || (returned == true && address(this).balance == beforeBalance));
    }

    receive() external payable {}
}

